// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 g) internal {
        uint balBefore = address(c).balance;
        bool reverted1;
        try c.settle() { reverted1 = false; }
        catch { reverted1 = true; }
        uint balMid = address(c).balance;
        bool reverted2;
        try c.settle() { reverted2 = false; }
        catch { reverted2 = true; }
        assertTrue(reverted1 && reverted2 && balMid == balBefore && address(c).balance == balBefore);
    }

    function testFuzz_run(bytes32 g) public {
        _run(g);
    }

    receive() external payable {}
}
